//! Completed explicit baseline operation DATA, never a source or write grant.
use crate::selected_exclusions_wire::{Seal,MAX_STREAM,MAX_HEADER};pub use crate::full_registry_check_wire::CheckFrame as Frame;use crate::full_registry_check_selection_wire::SelectionBinding;use serde::{Deserialize,Serialize};use std::{io,path::{Path,PathBuf}};
fn presence<'de,D:serde::Deserializer<'de>>(d:D)->Result<Option<Seal>,D::Error>{Option::<Seal>::deserialize(d)}
#[derive(Clone,Copy,Debug,Deserialize,Serialize,Eq,PartialEq)]pub enum Schema{#[serde(rename="native-baseline-update-v2")]V2}
#[derive(Clone,Copy,Debug,Default,Deserialize,Serialize,Eq,PartialEq,Ord,PartialOrd,Hash)]#[serde(rename_all="snake_case")]pub enum Mode{#[default]Update,Seed,Migrate}
#[derive(Clone,Debug,Deserialize,Serialize)]#[serde(deny_unknown_fields)]pub struct Terminal{pub schema:Schema,pub complete:bool,pub full_policy_parity:bool,pub root:PathBuf,pub mode:Mode,pub no_gen:bool,pub generation_committed:bool,pub selection:SelectionBinding,pub selected:u64,pub registered:u64,pub committed_files:u64,pub frame:Frame,#[serde(deserialize_with="presence")]pub diagnostics:Option<Seal>,pub report:Seal}
impl Terminal{pub fn require(&self,root:&Path,mode:Mode,no_gen:bool,selection:SelectionBinding)->io::Result<()>{
 let frame_invalid=match self.frame{Frame::Handlers{..}=>self.selected!=1,Frame::SourceHandlers{full_source_revision,full_semantic_revision,full_policy_revision,..}=>self.selected==self.registered||full_source_revision.is_some()!=full_semantic_revision.is_some()||full_source_revision.is_some()!=full_policy_revision.is_some(),_=>false};
 if frame_invalid||!self.complete||self.full_policy_parity||!root.is_absolute()||self.root!=root||self.mode!=mode||self.no_gen!=no_gen||self.selection!=selection||(no_gen&&self.generation_committed)||self.selected==0||self.selected>self.registered||self.committed_files>self.selected.checked_add(1).ok_or_else(invalid)?||self.report.length==0||self.report.length>MAX_STREAM||self.diagnostics.as_ref().is_some_and(|s|s.length==0||s.length>MAX_STREAM)||self.report.length.checked_add(self.diagnostics.as_ref().map_or(0,|s|s.length)).is_none_or(|n|n>MAX_STREAM){return Err(invalid())}Ok(())
}}
fn invalid()->io::Error{io::Error::new(io::ErrorKind::InvalidData,"baseline terminal differs from actual completed request/selection/producer/streams")}
/// Pre-mutation admission includes the largest genuine SourceHandlers shape.
pub fn require_header_room(root:&Path,selection:SelectionBinding,selected:u64,registered:u64)->io::Result<()>{let max=crate::selected_exclusions_wire::Hex128(u128::MAX);let t=Terminal{schema:Schema::V2,complete:true,full_policy_parity:false,root:root.into(),mode:Mode::Migrate,no_gen:false,generation_committed:false,selection,selected,registered,committed_files:selected.checked_add(1).ok_or_else(invalid)?,frame:Frame::SourceHandlers{query_revision:max,source_revision:max,policy_revision:max,handler_query_revision:max,partial_source_revision:Some(max),full_source_revision:Some(max),full_semantic_revision:Some(max),full_policy_revision:Some(max)},diagnostics:Some(Seal{length:MAX_STREAM,hash:max}),report:Seal{length:MAX_STREAM,hash:max}};let bytes=serde_json::to_vec(&t).map_err(io::Error::other)?;if bytes.len().checked_add(1).is_none_or(|n|n>MAX_HEADER){return Err(io::Error::new(io::ErrorKind::InvalidInput,"baseline workspace identity exceeds existing sealed header bound"))}Ok(())}

#[cfg(test)]mod controls{use super::*;fn terminal()->Terminal{let root=if cfg!(windows){PathBuf::from("E:/baseline-project")}else{PathBuf::from("/baseline-project")};let h=crate::selected_exclusions_wire::Hex128(1);Terminal{schema:Schema::V2,complete:true,full_policy_parity:false,root,mode:Mode::Update,no_gen:true,generation_committed:false,selection:SelectionBinding::for_selectors(&[]).unwrap(),selected:30,registered:30,committed_files:2,frame:Frame::Model{semantic_revision:h,source_revision:h,policy_revision:h},diagnostics:None,report:Seal{length:8,hash:h}}}
 #[test]fn baseline_terminal_requires_exact_workspace_gen_mode_completed_roster_and_both_stream_extents(){let mut t=terminal();t.require(&t.root,Mode::Update,true,t.selection).unwrap();assert!(t.require(&t.root,Mode::Seed,true,t.selection).is_err());assert!(t.require(&t.root,Mode::Migrate,true,t.selection).is_err());require_header_room(&t.root,t.selection,t.selected,t.registered).unwrap();assert!(t.require(&t.root,Mode::Update,false,t.selection).is_err());let root=t.root.join("other");assert!(t.require(&root,Mode::Update,true,t.selection).is_err());t.generation_committed=true;assert!(t.require(&t.root,Mode::Update,true,t.selection).is_err());t.generation_committed=false;t.committed_files=32;assert!(t.require(&t.root,Mode::Update,true,t.selection).is_err());t.committed_files=2;t.diagnostics=Some(Seal{length:MAX_STREAM,hash:t.report.hash});assert!(t.require(&t.root,Mode::Update,true,t.selection).is_err());t.diagnostics=None;t.complete=false;assert!(t.require(&t.root,Mode::Update,true,t.selection).is_err());}

 #[test]fn selected_baseline_terminal_binds_exact_selectors_and_each_actual_frame_shape(){
  let mut t=terminal();t.selection=SelectionBinding::for_selectors(&["scheduler".into(),"-unused".into()]).unwrap();t.selected=2;
  let h=t.report.hash;t.frame=Frame::Source{query_revision:h,source_revision:h,policy_revision:h};
  t.require(&t.root,Mode::Update,true,t.selection).unwrap();
  let other=SelectionBinding::for_selectors(&["-unused".into(),"scheduler".into()]).unwrap();
  assert!(t.require(&t.root,Mode::Update,true,other).is_err());
  t.frame=Frame::Handlers{query_revision:h,partial_source_revision:Some(h),full_source_revision:None};
  assert!(t.require(&t.root,Mode::Update,true,t.selection).is_err());t.selected=1;t.require(&t.root,Mode::Update,true,t.selection).unwrap();
  t.selected=2;t.frame=Frame::SourceHandlers{query_revision:h,source_revision:h,policy_revision:h,handler_query_revision:h,partial_source_revision:Some(h),full_source_revision:None,full_semantic_revision:None,full_policy_revision:None};
  t.require(&t.root,Mode::Update,true,t.selection).unwrap();
  if let Frame::SourceHandlers{full_source_revision,..}=&mut t.frame{*full_source_revision=Some(h)}
  assert!(t.require(&t.root,Mode::Update,true,t.selection).is_err());
  if let Frame::SourceHandlers{full_semantic_revision,full_policy_revision,..}=&mut t.frame{*full_semantic_revision=Some(h);*full_policy_revision=Some(h)}
  t.require(&t.root,Mode::Update,true,t.selection).unwrap();require_header_room(&t.root,t.selection,t.selected,t.registered).unwrap();
  let encoded=serde_json::to_vec(&t).unwrap();let decoded:Terminal=serde_json::from_slice(&encoded).unwrap();assert_eq!(decoded.frame,t.frame);
  t.selected=t.registered;assert!(t.require(&t.root,Mode::Update,true,t.selection).is_err());
 }
 #[test]fn baseline_terminal_requires_explicit_nullable_diagnostics_and_rejects_extra_authority_fields(){let t=terminal();let mut value=serde_json::to_value(&t).unwrap();value.as_object_mut().unwrap().remove("diagnostics");assert!(serde_json::from_value::<Terminal>(value).is_err());let mut value=serde_json::to_value(t).unwrap();value["source_grant"]=serde_json::json!(true);assert!(serde_json::from_value::<Terminal>(value).is_err());}}
